function practiceSet(rows) {
  return rows.map(([id, prompt, choices, answer, explanation, passage]) => ({
    id, prompt, choices, answer, explanation, passage
  }));
}

function makeMidtermSets(subject) {
  const [first, second] = midtermPracticeSets[subject];
  return [
    [...midtermStudy[subject].questions, ...first],
    [...second, ...midtermExtraQuestions[subject]]
  ];
}

